#[cfg(test)]
mod conformance_repairs {
    use crate::api::{BudgetedMatch, Regex};

    #[test]
    fn spec_witnesses() {
        for (pattern, flags, input, expected) in [
            (r"^(?<x>a)|(?<x>b)\k<x>$", "u", "bb", Some(0..2)),
            (r"^(?:(?<x>a)|(?<x>b))\k<x>$", "u", "b", None),
            (r"[a&&A]", "iv", "a", Some(0..1)),
            (r"[a--A]", "iv", "a", None),
            (r"[\q{}]", "v", "", Some(0..0)),
            (r"[\q{|ab}c]", "v", "c", Some(0..1)),
            (r"[\q{ab|a}]b", "v", "ab", Some(0..2)),
            (r"[\b]", "v", "\x08", Some(0..1)),
            (r"[a&]", "v", "a", Some(0..1)),
            (r"[!#]", "v", "#", Some(0..1)),
            (r"\P{Lowercase_Letter}", "iv", "a", None),
            (r"\P{Lowercase_Letter}", "iu", "a", Some(0..1)),
            (r"[\W]", "iu", "ſ", None),
            (r"[\W]", "iv", "ſ", None),
            (r"^((a*)*?)*b$", "u", "aaab", Some(0..4)),
            (r"^((a*)*?)*b$", "u", "aaa", None),
            (r"😀", "v", "x😀", Some(1..5)),
        ] {
            let re = Regex::with_flags(pattern, flags).unwrap();
            let actual = match re.find_from_budgeted(input, 0, 1_000_000) {
                BudgetedMatch::Match(m) => Some(m.range()),
                BudgetedMatch::NoMatch => None,
                BudgetedMatch::BudgetExhausted => panic!("exhausted {pattern}"),
            };
            assert_eq!(actual, expected, "{pattern} / {flags} on {input:?}");
        }
        let re = Regex::with_flags(r"(?<x>a)|(?<x>b)", "u").unwrap();
        let m = re.find("b").unwrap();
        assert_eq!(m.named_group("x"), Some(0..1));
        assert_eq!(m.captures, vec![None, Some(0..1)]);
    }

    #[test]
    fn spec_early_errors() {
        for pattern in [r"(?:(?<x>a)|b)(?:c|(?<x>d))", r"[^\q{}]", r"[^\q{ab}--\q{ab}]", r"[a&&&b]", r"[a--b&&c]", r"[!!]", r"\a", r"\1"] {
            assert!(Regex::with_flags(pattern, "v").is_err(), "{pattern}");
        }
        for pattern in [r"(?:(?<x>a)|(?<x>b))", r"[^\q{ab}&&a]", r"[^\q{a}]", r"[\q{a}&&a]"] {
            assert!(Regex::with_flags(pattern, "v").is_ok(), "{pattern}");
        }
    }

    #[cfg(feature = "utf16")]
    #[test]
    fn code_unit_ranges() {
        let re = Regex::with_flags(r"(?<x>😀)\k<x>", "v").unwrap();
        let input: Vec<u16> = "x😀😀".encode_utf16().collect();
        let m = re.find_from_utf16(&input, 0).next().unwrap();
        assert_eq!(m.range(), 1..5);
        assert_eq!(m.named_group("x"), Some(1..3));
        let re = Regex::with_flags(r"(a)\1", "").unwrap();
        let input: Vec<u16> = "😀aa".encode_utf16().collect();
        let m = re.find_from_ucs2(&input, 0).next().unwrap();
        assert_eq!(m.range(), 2..4);
        assert_eq!(m.group(1), Some(2..3));
    }
}
